def save_unique_records_seq(log_path, log_out, chain1_key, chain2_key, headers_subset):
    print("Processing: ", log_path)

    unique_seq_df = pd.read_csv("chainClusters.csv", sep="\t")

    unique_seq_df1 = unique_seq_df.rename(
        columns={"Chain": chain1_key, "Sequence ID": "Sequence ID 1"}
    )
    unique_seq_df2 = unique_seq_df.rename(
        columns={"Chain": chain2_key, "Sequence ID": "Sequence ID 2"}
    )

    df = pd.read_table(log_path)

    df = pd.merge(
        df, unique_seq_df1, on=["PDB Code", chain1_key], how="left", indicator=True
    )
    df = df.rename(columns={"_merge": "seq1 origin"})
    df = pd.merge(
        df, unique_seq_df2, on=["PDB Code", chain2_key], how="left", indicator=True
    )
    df = df.rename(columns={"_merge": "seq2 origin"})
    df = df.sort_values(by=["Distance"], ascending=True)

    df_recognised_seq_same_chains = df[
        ((df["seq1 origin"] == "both") | (df["seq2 origin"] == "both"))
        & (df[chain1_key] == df[chain2_key])
    ].drop_duplicates(subset=headers_subset + ["Sequence ID 1", "Sequence ID 2"])
    df_recognised_seq_different_chains = df[
        ((df["seq1 origin"] == "both") | (df["seq2 origin"] == "both"))
        & (df[chain1_key] != df[chain2_key])
    ].drop_duplicates(subset=headers_subset + ["Sequence ID 1", "Sequence ID 2"])

    df_not_recognised_seq = df[
        (df["seq1 origin"] == "left_only") & (df["seq2 origin"] == "left_only")
    ].drop_duplicates(subset=headers_subset + ["PDB Code"])

    df = pd.concat(
        [
            df_recognised_seq_same_chains,
            df_recognised_seq_different_chains,
            df_not_recognised_seq,
        ],
        ignore_index=True,
    )

    df.to_csv(log_out, sep="\t")
    num_lines = sum(1 for line in open(log_out)) - 1
    num_lines2 = sum(1 for line in open(log_path)) - 1

    print(num_lines)
    print(num_lines2)

    return log_out


