    def anion_pi_planar_hist_2d(
        df, png_name, bin, text="", min_x=0, max_x=90, min_y=0, max_y=180
    ):
        x = df["PlanarAngle"].tolist()
        plt.figure()
        plt.rcParams.update({"font.size": 16})
        # plt.hist2d(x, h, bins = bin, cmap=plt.cm.turbo, range= [[minX, maxX], [minY, maxY]])
        n, bins, patches = plt.hist(
            x,
            bin,
            density=False,
            range=(0, 90),
            facecolor="moccasin",
            edgecolor="orange",
        )
        # plt.colorbar()
        plt.xlabel("$\\it{\\alpha}$ / $^{\\circ}$ ")
        plt.xlim([0, 90])
        plt.ylabel("Number of occurences")
        if text != "":
            plt.text(
                70,
                0.7 * max(n),
                text,
                fontsize=20,
                color="k",
                horizontalalignment="center",
                verticalalignment="center",
                weight="bold",
            )
        plt.savefig(png_name, dpi=600, transparent=True, bbox_inches="tight")
        plt.close()

    main_planar_hist_dir = join(postprocessing_dir, "hist2d_planarAnions")
    for png_file in glob(join(main_planar_hist_dir, "*png")):
        remove(png_file)

    for plots_dir in [main_planar_hist_dir]:
        if not isdir(plots_dir):
            makedirs(plots_dir)

